const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',news:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h4M7 16h4M15 12h2M15 16h2"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h15V8H5a3 3 0 0 1 0-5"/><path d="M20 12h-6v5h6M16 14.5h1"/>',spark:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3ZM20 2v4M18 4h4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3ZM9 12l2 2 4-4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="m3 17 7-7 4 4 7-10M14 4h7v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const $=s=>document.querySelector(s),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const dateLabel=value=>value?new Date(value).toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short'}):'ไม่ระบุเวลา';
let stocks=[];
const stock=symbol=>stocks.find(s=>s.symbol===symbol)||{symbol,name:symbol,thai:'หุ้นไทยจากบัญชีเดิม',currency:'THB',sector:'Legacy',url:'https://www.set.or.th/'};
const defaults={holdings:[],alerts:{daily:true,news:true,trend:true,time:'08:00',scope:'portfolio'},sources:[]};
let state=structuredClone(defaults),committedState=structuredClone(defaults),currentUser=null,stateRevision=0,isSaving=false;
let page='overview',newsFilter='all',selectedStock='AAPL',query='',toastTimer;
let newsData={items:[],sources:[]},newsLoading=false,newsError='',newsEpoch=0;
async function save(){
  if(isSaving||!currentUser)return false;
  isSaving=true;
  try{
    const result=await api('/api/state',{method:'PUT',body:{state,userId:currentUser.id,revision:stateRevision}});
    state=result.state;stateRevision=result.revision;committedState=structuredClone(state);return true;
  }catch(error){
    state=structuredClone(committedState);
    if(error.status===401)showSignedOut('login');
    if(error.status===409){
      try{const latest=await api('/api/session');if(!latest.user||latest.user.id!==currentUser?.id)showSignedOut('login');else{state=latest.state;stateRevision=latest.revision;committedState=structuredClone(state);if($('#modal').open)$('#modal').close();render();}}catch{showSignedOut('login');}
    }
    toast(error.message);return false;
  }finally{isSaving=false}
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}

function resetNews(){newsEpoch++;newsLoading=false;newsData={items:[],sources:[]};newsError='';}
async function loadNews({redraw=true}={}){
 if(!currentUser||newsLoading)return;const userId=currentUser.id,epoch=++newsEpoch;newsLoading=true;newsError='';
 try{const result=await api('/api/news');if(epoch!==newsEpoch||currentUser?.id!==userId)return;newsData=result;}
 catch(error){if(epoch!==newsEpoch)return;newsError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===newsEpoch){newsLoading=false;if(redraw&&currentUser&&['overview','news','alerts'].includes(page))render();}}
}
function header(title,sub,action=''){return `<div class="page-header"><div><div class="eyebrow">YOUR US MARKET WORKSPACE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${action}</div></div>`;}
const addButton=()=>`<button class="btn primary" data-action="add">${icon('plus')} เพิ่มหุ้น</button>`;
function portfolioCost(currency){return state.holdings.filter(h=>stock(h.symbol).currency===currency).reduce((sum,h)=>sum+h.qty*h.cost,0);}
function newsItem(n){return `<article class="news-card"><span class="company-logo">${escapeHtml(n.symbol.slice(0,3))}</span><div><div class="news-meta"><span class="ticker-tag">${escapeHtml(n.symbol)}</span><span>${escapeHtml(n.source)}</span>${n.stale?'<span class="sentiment negative">ข้อมูลเก่า · อัปเดตไม่สำเร็จ/ล่าช้า</span>':''}</div><a class="news-title" href="${escapeHtml(n.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(n.title)} ↗</a><div class="news-footer"><span>เผยแพร่ ${escapeHtml(dateLabel(n.publishedAt))}</span><span>ประกาศบริษัท · อ่านต้นฉบับ</span></div></div></article>`;}
function feedStatus(){return `<details class="feed-status"><summary>สถานะแหล่งข่าว ${newsData.sources.filter(s=>s.status==='ok').length}/${newsData.sources.length} เชื่อมต่อสำเร็จ</summary>${newsData.sources.map(s=>`<p><b>${escapeHtml(s.name)}</b> · ${s.status==='ok'?'เชื่อมต่อแล้ว':s.status==='error'?'เชื่อมต่อไม่สำเร็จ':'รอข้อมูล'}${s.enabled?'':' · ปิดในบัญชีนี้'}<br><small>ดึงข้อมูลสำเร็จล่าสุด ${escapeHtml(dateLabel(s.succeededAt))}${s.error?' · '+escapeHtml(s.error):''}</small></p>`).join('')}<p>ตรวจทุก 15 นาทีขณะเซิร์ฟเวอร์ทำงาน เวลาเผยแพร่ข่าวอาจเก่ากว่าเวลาที่ดึงข้อมูล</p></details>`;}
function newsSection(compact=false){const items=newsData.items.filter(n=>newsFilter!=='portfolio'||state.holdings.some(h=>h.symbol===n.symbol));return `<section class="card"><div class="section-title"><h2>ประกาศจากบริษัท</h2><button class="text-button" data-refresh-news ${newsLoading?'disabled':''}>${newsLoading?'กำลังโหลด…':'รีเฟรช'}</button></div><div class="tabs"><button class="tab ${newsFilter==='all'?'active':''}" data-filter="all">แหล่งข่าวที่เปิดไว้</button><button class="tab ${newsFilter==='portfolio'?'active':''}" data-filter="portfolio">หุ้นในพอร์ต</button></div>${newsError?`<p role="alert" class="form-error">${escapeHtml(newsError)}</p>`:''}${(compact?items.slice(0,5):items).map(newsItem).join('')||`<div class="empty">${newsLoading?'กำลังโหลดข่าว…':'ยังไม่มีข่าวในรายการนี้'}<br><small>ฟีดเริ่มต้นครอบคลุม AAPL, MSFT และ NVDA<br>ตรวจสถานะแหล่งข่าว หรือเลือกหุ้นในพอร์ตให้ตรงกับฟีด</small></div>`}${feedStatus()}<p class="small-note">หัวข้อจาก RSS ต้นทาง ยังไม่สรุปด้วย AI ประกาศบริษัทอาจมีมุมมองทางการตลาด ควรตรวจสอบข้อมูลอื่นประกอบ</p></section>`;}
function aiCard(){return `<section class="ai-card"><div class="section-title"><h2>AI Insights</h2><span class="demo-label">ยังไม่เปิดใช้</span></div><label class="field">บริษัท<select id="ai-symbol">${stocks.map(s=>`<option ${s.symbol===selectedStock?'selected':''} value="${s.symbol}">${s.symbol} — ${s.name}</option>`).join('')}</select></label><div class="ai-trend">ยังประเมินไม่ได้</div><p>ยังไม่มีบริการ AI และข้อมูลราคาที่ผ่านการตรวจสอบ จึงยังไม่แสดงคำทำนายขึ้น/ลงหรือเปอร์เซ็นต์</p><div class="risk-inline">⚠ AI อาจคาดการณ์ผิดพลาด ไม่ใช่คำแนะนำการลงทุน</div></section>`;}
function renderOverview(){return header('มองข่าวสหรัฐฯ ให้เห็นภาพ','พอร์ตของคุณและข่าวจากบริษัทต้นทาง',addButton())+`<div class="dashboard-columns"><div class="left-column"><section class="daily-brief"><div class="brief-top">US EQUITIES · PERSONAL WORKSPACE</div><h2>เริ่มจากบริษัท<br>ที่คุณอยากรู้จักให้มากขึ้น</h2><p>ติดตามประกาศบริษัท อ่านต้นฉบับ และจัดเก็บหุ้นที่ถืออยู่<br>ข้อมูลที่ขาดจะแสดงสถานะตรงไปตรงมา</p><div class="brief-bottom"><span>12 บริษัท · 3 ฟีดข่าวต้นทาง</span><button class="text-button" data-page="search">ค้นหาบริษัท ${icon('arrow')}</button></div></section>${newsSection(true)}</div><div class="right-column"><section class="card"><span class="small-label">ต้นทุนหุ้นสหรัฐฯ ที่คุณบันทึก</span><div class="portfolio-amount">$${money(portfolioCost('USD'))}</div><p class="small-note">${state.holdings.length} หุ้นในพอร์ต · ไม่ใช่มูลค่าตลาด<br>ยังไม่ได้เชื่อมราคาหุ้น ไม่มีข้อมูลกำไร/ขาดทุน</p><button class="btn full-button" data-page="portfolio">จัดการพอร์ต</button></section>${aiCard()}</div></div>`;}
function renderPortfolio(){return header('พอร์ตของฉัน','บันทึกจำนวนหุ้นและต้นทุน รองรับเศษหุ้น 6 ตำแหน่ง',addButton())+`<div class="summary-grid"><section class="card"><span class="small-label">ต้นทุนรวม USD</span><div class="summary-value">$${money(portfolioCost('USD'))}</div></section><section class="card"><span class="small-label">ราคาตลาด / กำไรขาดทุน</span><div class="summary-value">ยังไม่มีข้อมูล</div></section>${state.holdings.some(h=>stock(h.symbol).currency==='THB')?`<section class="card"><span class="small-label">ต้นทุนหุ้นไทยเดิม · THB แยกจาก USD</span><div class="summary-value">฿${money(portfolioCost('THB'))}</div></section>`:''}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>หุ้น / บริษัท</th><th>จำนวนหุ้น</th><th>ต้นทุนต่อหุ้น</th><th>ต้นทุนรวม</th><th>จัดการ</th></tr></thead><tbody>${state.holdings.map(h=>`<tr><td><b>${escapeHtml(h.symbol)}</b><small>${escapeHtml(stock(h.symbol).name)}</small></td><td>${Number(h.qty).toLocaleString('en-US',{maximumFractionDigits:6})}</td><td>${stock(h.symbol).currency} ${money(h.cost)}</td><td>${money(h.cost*h.qty)}</td><td><button class="text-button" data-edit="${escapeHtml(h.symbol)}">แก้ไข</button><button class="remove" data-remove="${escapeHtml(h.symbol)}">นำออก</button></td></tr>`).join('')}</tbody></table>${state.holdings.length?'':'<div class="empty">ยังไม่มีหุ้นในพอร์ต เริ่มเพิ่มหุ้นที่คุณสนใจได้เลย</div>'}</div><p class="small-note">บันทึกแยกตามบัญชีบนเซิร์ฟเวอร์ · ไม่รวมค่าธรรมเนียม เงินปันผล หรืออัตราแลกเปลี่ยน</p><a class="text-button" href="/api/export" download>ดาวน์โหลดข้อมูลบัญชี JSON ↗</a></section>`;}
function companyCards(){const q=query.trim().toLowerCase(),list=stocks.filter(s=>`${s.symbol} ${s.name} ${s.thai} ${s.sector}`.toLowerCase().includes(q));return list.map(s=>`<article class="card company-card"><span class="company-logo">${s.symbol.slice(0,3)}</span><h3>${s.symbol} <span class="unit">US · USD</span></h3><p>${s.name}<br>${s.thai} · ${s.sector}</p><button class="btn" data-company="${s.symbol}">ดูข้อมูลบริษัท ${icon('arrow')}</button></article>`).join('')||'<div class="empty">ไม่พบในรายชื่อ 12 บริษัทที่รองรับ<br>ลอง AAPL, Microsoft, NVIDIA หรือ แอปเปิล</div>';}
function renderSearch(){return header('ค้นหาบริษัทสหรัฐฯ','ค้นหาชื่อบริษัท ตัวย่อหุ้น หรือชื่อภาษาไทย')+`<label class="large-search">${icon('search')}<input id="company-query" type="search" placeholder="เช่น AAPL, Microsoft, แอปเปิล" value="${escapeHtml(query)}" aria-label="ค้นหาบริษัท"></label><p class="small-note">รายชื่อเริ่มต้น 12 บริษัท ไม่ใช่ทุกบริษัทในตลาดสหรัฐฯ</p><div class="company-grid" id="company-results">${companyCards()}</div>`;}
function renderAlerts(){const a=state.alerts,items=a.news?newsData.items.filter(n=>a.scope==='all'||state.holdings.some(h=>h.symbol===n.symbol)).slice(0,10):[];return header('ข่าวที่ติดตาม & การตั้งค่า','อ่านข่าวที่เกี่ยวข้องในแอป และจัดการบัญชี')+`<section class="card"><h2>ข่าวจากบริษัทที่คุณติดตาม</h2>${items.map(newsItem).join('')||'<div class="empty">ยังไม่มีข่าวที่ตรงกับการตั้งค่า</div>'}<p class="small-note">รายการข่าวภายในแอป ไม่ใช่ Push หรืออีเมล ไม่ส่งเตือนเมื่อปิดแอป</p></section><form id="alert-form" class="card settings"><div class="info-box">ตั้งค่าการกรองข่าวได้แล้ว ส่วนสรุปรายวันและแจ้งแนวโน้มจะเก็บเป็นความต้องการ ยังไม่เปิดส่งอัตโนมัติ</div>${[['news','แสดงข่าวหุ้นที่ติดตาม'],['daily','สรุปรายวัน · ยังไม่เปิดส่ง'],['trend','การเปลี่ยนแนวโน้ม AI · ยังไม่เปิดใช้']].map(([key,label])=>`<label class="setting-row"><span>${label}</span><input class="switch" type="checkbox" name="${key}" ${a[key]?'checked':''}></label>`).join('')}<label class="setting-row">เวลาที่ต้องการรับสรุป (เวลาไทย)<input type="time" name="time" required value="${escapeHtml(a.time)}"></label><label class="setting-row">ขอบเขตข่าว<select name="scope"><option value="portfolio" ${a.scope==='portfolio'?'selected':''}>หุ้นในพอร์ต</option><option value="all" ${a.scope==='all'?'selected':''}>ทุกฟีดที่เปิดไว้</option></select></label><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></form><section class="card settings"><h2>กู้คืนบัญชี</h2><p>เก็บรหัสกู้คืนไว้ในที่ปลอดภัย หากลืมรหัสผ่านใช้รหัสนี้ได้ การสร้างใหม่จะยกเลิกรหัสเดิม</p><button class="btn" data-new-recovery>สร้างรหัสกู้คืนใหม่</button></section>`;}
function render(){if(!currentUser)return;const names={overview:'ภาพรวม',news:'ข่าวสาร',portfolio:'พอร์ตของฉัน',insights:'AI Insights',search:'ค้นหาบริษัท',alerts:'การแจ้งเตือน',sources:'แหล่งข้อมูล'};$('#breadcrumb').textContent=names[page];document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);if(n.dataset.page===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});const views={overview:renderOverview,news:()=>header('ประกาศบริษัท','หัวข้อข่าวต้นทางพร้อมลิงก์และเวลาเผยแพร่')+newsSection(),portfolio:renderPortfolio,search:renderSearch,alerts:renderAlerts,sources:renderSourceManager,insights:()=>header('AI Insights','สถานะการเชื่อมต่อและข้อจำกัด')+`<div class="wide-ai"><section class="card agent-notice"><div><h3>Custom GPT ของคุณ · ยังไม่ได้เชื่อมต่อ</h3><p>ยังไม่เปิดสรุปข่าวด้วย AI หรือคาดการณ์ราคาในแอป</p></div></section>${aiCard()}</div>`};$('#main').innerHTML=views[page]();}
function navigate(next){if(!currentUser)return;page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function addHolding(symbol='AAPL',edit=false){const h=edit?state.holdings.find(v=>v.symbol===symbol):null,options=stocks.some(s=>s.symbol===symbol)?stocks:[...stocks,stock(symbol)];openModal(edit?'แก้ไขหุ้นในพอร์ต':'เพิ่มหุ้นที่คุณถืออยู่',`<form id="holding-form" data-edit="${edit?'yes':'no'}"><label class="field">บริษัท<select name="symbol" ${edit?'disabled':''}>${options.map(s=>`<option value="${s.symbol}" ${s.symbol===symbol?'selected':''}>${s.symbol} — ${s.name}</option>`).join('')}</select></label><label class="field">จำนวนหุ้น<input type="number" name="qty" min="0.000001" max="1000000000" step="0.000001" required value="${h?h.qty:''}"></label><label class="field">ต้นทุนเฉลี่ยต่อหุ้น (${stock(symbol).currency})<input type="number" name="cost" min="0" max="10000000" step="any" required value="${h?h.cost:''}"></label><p class="form-help">${edit?'แทนที่จำนวนและต้นทุนเดิม':'หากมีหุ้นนี้แล้ว จะรวมจำนวนและคำนวณต้นทุนเฉลี่ยใหม่'}</p><button class="btn primary" type="submit">บันทึกหุ้นในพอร์ต</button></form>`);}
document.addEventListener('click',async e=>{
 if(!currentUser)return;const el=e.target.closest('button,a');if(!el)return;if(isSaving){toast('กำลังบันทึก กรุณารอสักครู่');return;}
 if(el.dataset.page)navigate(el.dataset.page);if(el.id==='quick-search'){navigate('search');$('#company-query').focus();}if(el.id==='close-modal')$('#modal').close();
 if(el.dataset.filter){newsFilter=el.dataset.filter;render();}if(el.hasAttribute('data-refresh-news')){loadNews();render();}if(el.dataset.action==='add')addHolding();if(el.dataset.edit)addHolding(el.dataset.edit,true);
 if(el.dataset.remove)openModal('นำหุ้นออกจากพอร์ต',`<p>นำ ${escapeHtml(el.dataset.remove)} ออกจากพอร์ต?</p><button class="btn primary" data-confirm-remove="${escapeHtml(el.dataset.remove)}">ยืนยันนำออก</button>`);
 if(el.dataset.confirmRemove){state.holdings=state.holdings.filter(h=>h.symbol!==el.dataset.confirmRemove);const ok=await save();$('#modal').close();render();if(ok)toast('นำหุ้นออกแล้ว');}
 if(el.dataset.company){const s=stock(el.dataset.company);openModal(s.symbol+' · '+s.name,`<p>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><div class="info-box">ราคาหุ้น: ยังไม่มีข้อมูล · ไม่มีการคาดการณ์ราคา</div><p><a class="text-button" href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">เว็บไซต์นักลงทุนสัมพันธ์ ↗</a></p><p><a class="text-button" href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(s.symbol)}" target="_blank" rel="noopener noreferrer">ค้นเอกสารกับ SEC EDGAR ↗</a></p><button class="btn primary" data-add-symbol="${s.symbol}">เพิ่มหุ้นนี้ในพอร์ต</button>`);}
 if(el.dataset.addSymbol)addHolding(el.dataset.addSymbol);
 if(el.hasAttribute('data-new-recovery'))openModal('สร้างรหัสกู้คืนใหม่','<form id="new-recovery-form"><label class="field">ยืนยันรหัสผ่านปัจจุบัน<input type="password" name="password" autocomplete="current-password" maxlength="128" required></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">สร้างรหัสใหม่</button></form>');
});
document.addEventListener('input',e=>{if(e.target.id==='company-query'){query=e.target.value;$('#company-results').innerHTML=companyCards();}});
document.addEventListener('change',e=>{if(e.target.id==='ai-symbol'){selectedStock=e.target.value;render();}});
document.addEventListener('submit',async e=>{
 if(!currentUser)return;const f=e.target;if(isSaving){e.preventDefault();return;}
 if(f.id==='holding-form'){e.preventDefault();const symbol=f.elements.symbol.value,qty=Number(f.elements.qty.value),cost=Number(f.elements.cost.value);if(!Number.isFinite(qty)||qty<0.000001||qty>1e9||!Number.isFinite(cost)||cost<0||cost>1e7)return;const existing=state.holdings.find(h=>h.symbol===symbol);if(existing){if(f.dataset.edit==='yes'){existing.qty=qty;existing.cost=cost;}else{const total=Math.round((existing.qty+qty)*1e6)/1e6;if(total>1e9){toast('จำนวนหุ้นรวมเกินขอบเขต');return;}existing.cost=(existing.cost*existing.qty+cost*qty)/total;existing.qty=total;}}else state.holdings.push({symbol,qty,cost});const ok=await save();$('#modal').close();render();if(ok)toast(`บันทึก ${symbol} แล้ว`);}
 if(f.id==='alert-form'){e.preventDefault();state.alerts={daily:f.elements.daily.checked,news:f.elements.news.checked,trend:f.elements.trend.checked,time:f.elements.time.value,scope:f.elements.scope.value};if(await save()){render();toast('บันทึกการตั้งค่าแล้ว');}}
 if(f.id==='new-recovery-form'){e.preventDefault();const button=f.querySelector('button');if(button.disabled)return;button.disabled=true;try{const result=await api('/api/recovery-code',{method:'POST',body:{password:f.elements.password.value}});if(currentUser)openModal('เก็บรหัสกู้คืนใหม่',recoveryNotice(result.recoveryCode));}catch(error){f.querySelector('.form-error').textContent=error.message;}finally{button.disabled=false;}}
});
document.addEventListener('keydown',e=>{if(currentUser&&e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();navigate('search');$('#company-query').focus();}});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
setInterval(()=>{if(currentUser&&!isSaving&&document.visibilityState==='visible')loadNews({redraw:!$('#modal').open});},5*60*1000);
